'use client';
import {passkeyTools} from '../lib/passkeys';

import {createContext,useContext,useCallback,useEffect,useRef,useState,type FormEvent,type ReactNode} from 'react';
import '../app/account/account.css';
import CallLogs from '../app/account/call-logs';
import {formatSiteDate,setSiteTimeZone,siteDateInputToISO} from '../lib/site-time';
import {LoadingPlaceholder} from './loading-placeholder';
import {EmailField} from './email-field';
import {ProviderIcon} from './provider-icon';
import {validPassword} from '../lib/account-validation';
import {ShieldCheck,Wallet,KeyRound,History,UserRound,LogOut,Package,Monitor,ArrowLeft} from 'lucide-react';

type Options={time_zone?:string;website_url?:string;registration?:boolean;registration_enabled?:boolean;mail_available?:boolean;allowed_email_domains?:string[];email_login?:boolean;github?:boolean;google?:boolean;telegram?:boolean;turnstile?:boolean;turnstile_site_key?:string;admin_path?:string};
type Profile={confirmation_method?:'password'|'passkey';uid:string;time_zone?:string;personal_time_zone?:string;nickname:string;email_verified:boolean;totp_enabled:boolean;user:{id:string;username:string;email:string};levels:{name:string;display_name:string}[];permissions:string[]};
type Plan={id:string;name:string;description:string;price_micros:number;days:number;hourly:number;daily:number;monthly:number};
type WalletData={wallet:{balance_micros:number;held_micros:number};subscription:(Plan&{plan_name:string;plan_id:string;expires_at:string;time_zone?:string})|null;usage?:{hourly:number;daily:number;monthly:number}};
type Row=Record<string,any>;
type CaptchaAPI={render:(el:HTMLElement,args:Record<string,unknown>)=>string;remove:(id:string)=>void};
declare global {interface Window{turnstile?:CaptchaAPI}}
class RequestError extends Error{constructor(message:string,readonly status:number){super(message)}}
const money=(value:number)=>((value||0)/1000000).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:6});
const date=formatSiteDate;
async function api<T=any>(path:string,method='GET',body?:unknown,signal?:AbortSignal):Promise<T>{
 const usePasskey=!!(body&&typeof body==='object'&&'__passkey' in body&&(body as Record<string,unknown>).__passkey);const init:RequestInit={method,credentials:'same-origin',cache:'no-store',redirect:'error',headers:{'Content-Type':'application/json','X-API-Request':'1'},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:signal||AbortSignal.timeout(15000)};const request=usePasskey?await (await passkeyTools()).prepare(path,init):new Request(new URL(path,location.origin),init);if(!usePasskey&&body&&typeof body==='object'&&'__passkey' in body){const cleaned={...(body as Record<string,unknown>)};delete cleaned.__passkey;init.body=JSON.stringify(cleaned)}const response=await fetch(usePasskey?request:new Request(new URL(path,location.origin),init));
 const data=await response.json().catch(()=>({}));if(!response.ok)throw new RequestError(data.error||'操作未完成，请稍后重试',response.status);return data;
}
function broadcast(){const channel=typeof BroadcastChannel==='function'?new BroadcastChannel('api-manager-auth'):null;channel?.postMessage('changed');channel?.close()}
function useCaptcha(){const [token,setToken]=useState(''),[epoch,setEpoch]=useState(0);const reset=()=>{setToken('');setEpoch(n=>n+1)};return {token,onToken:setToken,epoch,reset}}
function Captcha({options,action,control}:{options:Options;action:string;control:ReturnType<typeof useCaptcha>}){
 const ref=useRef<HTMLDivElement>(null);const {onToken,epoch}=control;
 useEffect(()=>{
  if(!options.turnstile)return;let cancelled=false,id:string|undefined;
  const attach=()=>{if(window.turnstile&&ref.current&&!cancelled&&id===undefined)id=window.turnstile.render(ref.current,{sitekey:options.turnstile_site_key,action,callback:onToken,'expired-callback':()=>onToken(''),'error-callback':()=>onToken(''),theme:'light'})};
  let script=document.getElementById('turnstile-script') as HTMLScriptElement|null;
  if(!script){script=document.createElement('script');script.id='turnstile-script';script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.async=true;document.head.appendChild(script)}
  script.addEventListener('load',attach);attach();return()=>{cancelled=true;script?.removeEventListener('load',attach);if(id!==undefined)window.turnstile?.remove(id)};
 },[options.turnstile,options.turnstile_site_key,action,onToken,epoch]);
 return options.turnstile?<div ref={ref} className="account-captcha" aria-label="人机验证"/>:null;
}
function Dialog({open,title,children,onClose}:{open:boolean;title:string;children:ReactNode;onClose:()=>void}){
 const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{if(open&&!ref.current?.open)ref.current?.showModal();if(!open&&ref.current?.open)ref.current?.close()},[open]);
 return <dialog ref={ref} className="account-dialog" onCancel={e=>{e.preventDefault();onClose()}} aria-label={title}><h2>{title}</h2>{children}</dialog>;
}
const ConfirmationContext=createContext<'password'|'passkey'>('password');
function Fields({totp,required=true}:{totp:boolean;required?:boolean}){const method=useContext(ConfirmationContext);return <fieldset className="confirmation-fields"><legend>确认身份</legend><input type="hidden" name="confirmation_method" value={method}/>{method==='password'?<><label>当前密码<input name="current_password" type="password" autoComplete="current-password" maxLength={72} required={required}/></label>{totp&&<label>动态码或恢复码<input name="totp_code" autoComplete="one-time-code" maxLength={64} required={required}/></label>}</>:<p className="account-note">提交后使用通行密钥确认此操作。可在账号安全中修改默认确认方式。</p>}</fieldset>}
function stepup(fields:FormData,token:string){return {current_password:String(fields.get('current_password')||''),totp_code:String(fields.get('totp_code')||''),turnstile_token:token,__passkey:fields.get('confirmation_method')==='passkey'}}
const tabs=[['overview','账户概览',Wallet],['basic','基础资料',UserRound],['plans','套餐',Package],['redeem','卡密兑换',KeyRound],['ledger','余额流水',History],['keys','调用凭据',KeyRound],['logs','调用日志',History],['security','账号安全',ShieldCheck],['sessions','设备与会话',Monitor]] as const;

export function AccountExperience({authPage}:{authPage?:'login'|'register'}){
 const [authConfigLoading,setAuthConfigLoading]=useState(true);
 const [options,setOptions]=useState<Options>({}),[profile,setProfile]=useState<Profile|null>(null),[loading,setLoading]=useState(true),[view,setView]=useState('overview'),[message,setMessage]=useState(''),[busy,setBusy]=useState(false),[wallet,setWallet]=useState<WalletData|null>(null),[rows,setRows]=useState<Row[]>([]),[newKey,setNewKey]=useState(''),[recovery,setRecovery]=useState<string[]>([]),[dataLoading,setDataLoading]=useState(false);
 const lock=useRef(false),identity=useRef(''),generation=useRef(0);
 const refresh=useCallback(async()=>{const epoch=++generation.current;try{const next=await api<Profile>('/account/v1/me');if(epoch===generation.current){setSiteTimeZone(next.time_zone);if(identity.current&&identity.current!==next.uid){setNewKey('');setRecovery([]);setRows([]);setWallet(null);setView('overview')};identity.current=next.uid;setProfile(next)}}catch(e){if(epoch===generation.current&&e instanceof RequestError&&e.status===401){identity.current='';setProfile(null);setNewKey('');setRows([]);setWallet(null)}else if(epoch===generation.current)setMessage('暂时无法确认登录状态，请刷新重试')}finally{if(epoch===generation.current)setLoading(false)}},[]);
 useEffect(()=>{void api<Options>('/account/v1/options').then(value=>{setOptions(value)}).catch(()=>setMessage('登录配置暂不可用')).finally(()=>setAuthConfigLoading(false));void refresh();const channel=typeof BroadcastChannel==='function'?new BroadcastChannel('api-manager-auth'):null;const update=()=>void refresh();channel?.addEventListener('message',update);window.addEventListener('focus',update);return()=>{++generation.current;channel?.close();window.removeEventListener('focus',update)}},[refresh]);
 const loadData=useCallback(async(signal?:AbortSignal)=>{
  const uid=identity.current;if(!uid)return;setDataLoading(true);try{
   const endpoints:Record<string,string>={ledger:'/account/v1/wallet/ledger',plans:'/account/v1/plans',keys:'/account/v1/keys',sessions:'/account/v1/sessions'};
   if((view==='overview'||view==='plans')&&(profile?.permissions.includes('*')||profile?.permissions.includes('account.billing.read'))){const next=await api<WalletData>('/account/v1/wallet','GET',undefined,signal);if(identity.current===uid&&!signal?.aborted)setWallet(next)}
   if(endpoints[view]){const next=await api<Row[]>(endpoints[view],'GET',undefined,signal);if(identity.current===uid&&!signal?.aborted)setRows(next||[])}
  }catch(e){if(!signal?.aborted&&identity.current===uid)setMessage(e instanceof Error?e.message:'数据读取失败')}finally{if(!signal?.aborted)setDataLoading(false)}
 },[view,profile?.permissions.join(',')]);
 useEffect(()=>{const controller=new AbortController();setMessage('');setRows([]);void loadData(controller.signal);return()=>controller.abort()},[profile?.uid,loadData]);
 useEffect(()=>{if(!profile?.uid||!['overview','plans'].includes(view))return;const controller=new AbortController();const update=()=>{if(!document.hidden)void loadData(controller.signal)};window.addEventListener('focus',update);const timer=setInterval(update,60000);return()=>{controller.abort();clearInterval(timer);window.removeEventListener('focus',update)}},[profile?.uid,view,loadData]);
 async function act(fn:()=>Promise<void>){if(lock.current)return;lock.current=true;setBusy(true);setMessage('');try{await fn()}catch(e){setMessage(e instanceof Error?e.message:'操作未完成')}finally{lock.current=false;setBusy(false)}}
 const can=(code:string)=>!!profile&&(profile.permissions.includes('*')||profile.permissions.includes(code));const tabPermissions:Record<string,string>={basic:'account.profile',keys:'account.keys.read',logs:'account.logs',plans:'account.billing.read',ledger:'account.billing.read',security:'account.security',sessions:'account.sessions',redeem:'account.billing.redeem'};
 const adminPath=options.admin_path?.startsWith('/')&&!options.admin_path.startsWith('//')?options.admin_path:'/admin';
 return <ConfirmationContext.Provider value={profile?.confirmation_method||'password'}><main className="account-page"><link rel="stylesheet" href="/ui/admin.css"/><link rel="stylesheet" href="/ui/controls.css"/>
  <header className="account-header"><a href="/"><ArrowLeft size={17}/>网站首页</a><strong>用户中心</strong><div>{profile&&profile.permissions.some(p=>p==='*'||(!p.startsWith('account.')&&p!=='api.test'))&&<button disabled={busy} onClick={()=>void act(async()=>{const entry=await api<{url:string}>('/account/v1/admin-entry','POST',{});if(entry.url!==adminPath+'/')throw new Error('管理后台入口不可用');location.assign(entry.url)})}>管理后台</button>}{profile&&<button disabled={busy} onClick={()=>void act(async()=>{await api('/auth/v1/logout','POST');generation.current++;identity.current='';setProfile(null);setRows([]);setNewKey('');setWallet(null);setRecovery([]);broadcast()})}><LogOut size={16}/>退出登录</button>}</div></header>
  <Dialog open={!!message&&!recovery.length} title="操作提示" onClose={()=>setMessage('')}><p className="dialog-feedback">{message}</p><button type="button" onClick={()=>setMessage('')}>我知道了</button></Dialog>
  {loading||(!profile&&authConfigLoading)?<LoadingPlaceholder className="account-loading-shell"/>:!profile?<Auth initialPage={authPage} options={options} busy={busy} act={act} onLogin={async()=>{broadcast();await refresh()}} setMessage={setMessage}/>:<div className="account-layout">
   <aside className="account-sidebar"><strong>{profile.nickname||profile.user.username}</strong><small>{profile.user.email||'尚未设置邮箱'}</small><nav aria-label="用户中心导航">{tabs.filter(([id])=>!tabPermissions[id]||can(tabPermissions[id])).map(([id,title,Icon])=><button key={id} className={view===id?'active':''} aria-current={view===id?'page':undefined} onClick={()=>{setView(id);setNewKey('')}}><Icon size={18}/>{title}</button>)}</nav></aside>
   <section className="account-content" aria-busy={dataLoading}><h1>{tabs.find(t=>t[0]===view)?.[1]}</h1>
    {dataLoading&&<span className="account-loading-indicator" role="status" aria-label="内容加载中"><span className="auth-spinner" aria-hidden="true"/></span>}<>
     {view==='overview'&&<><div className="account-stats">{can('account.billing.read')&&<><section><span>可用余额</span><strong>¥ {money((wallet?.wallet.balance_micros||0)-(wallet?.wallet.held_micros||0))}</strong><small>预留金额 ¥ {money(wallet?.wallet.held_micros||0)}</small></section><section><span>当前套餐</span><strong>{wallet?.subscription?.plan_name||'按次计费'}</strong><small>{wallet?.subscription?'有效至 '+date(wallet.subscription.expires_at):'按接口公示价格结算'}</small></section></>}<section><span>账号保护</span><strong>{profile.totp_enabled?'双重验证已启用':'建议开启双重验证'}</strong><small>{profile.email_verified?'邮箱已验证':'邮箱待验证'}</small></section></div><dl className="account-details"><div><dt>唯一 UID</dt><dd>{profile.uid}</dd></div><div><dt>用户等级</dt><dd>{profile.levels.filter(level=>(profile as any).user.roles?.includes(level.name)||(profile as any).user.role===level.name).map(level=>level.display_name||level.name).join('、')||'会员'}</dd></div></dl>{can('account.billing.read')&&<PlanUsage wallet={wallet}/>}</>}
     {view==='redeem'&&can('account.billing.redeem')&&<Redeem busy={busy} act={act} reload={loadData} setMessage={setMessage}/>}
     {view==='basic'&&can('account.profile')&&<BasicProfile profile={profile} options={options} busy={busy} act={act} refresh={refresh} setMessage={setMessage}/>}
     {view==='plans'&&can('account.billing.read')&&<Plans canPurchase={can('account.billing.purchase')} plans={rows as Plan[]} wallet={wallet} busy={busy} act={act} reload={loadData} setMessage={setMessage}/>}
     {view==='keys'&&can('account.keys.read')&&<Keys key={profile.uid} rows={rows} options={options} profile={profile} busy={busy} act={act} reload={loadData} secret={newKey} setSecret={value=>{if(identity.current===profile.uid)setNewKey(value)}}/>}
     {view==='ledger'&&can('account.billing.read')&&<Table headers={['时间','类型 / 原因','金额','余额']} rows={rows.map(v=>[date(v.created_at),v.note||v.kind,'¥ '+money(v.amount_micros),'¥ '+money(v.balance_micros)])} empty="暂无余额流水。"/>}
     {view==='logs'&&can('account.logs')&&<CallLogs key={profile.uid}/>}
     {view==='sessions'&&can('account.sessions')&&<Sessions key={profile.uid} profile={profile} options={options} rows={rows} busy={busy} act={act} reload={loadData} refresh={refresh}/>}
     {view==='security'&&can('account.security')&&<Security key={profile.uid} profile={profile} options={options} busy={busy} act={act} refresh={refresh} setMessage={setMessage} setRecovery={codes=>{if(!identity.current||identity.current===profile.uid)setRecovery(codes)}}/>}
    </>
   </section>
  </div>}
  <Dialog open={recovery.length>0} title="请保存恢复码" onClose={()=>{}}><p>以下恢复码仅显示一次。每个码只能使用一次，请离线保存。安全设置已更新，需重新登录。</p><div className="account-secret">{recovery.map(code=><code key={code}>{code}</code>)}</div><button onClick={()=>setRecovery([])}>我已保存，返回登录</button></Dialog>
 </main></ConfirmationContext.Provider>;
}

function Auth({initialPage,options,busy,act,onLogin,setMessage}:{initialPage?:'login'|'register';options:Options;busy:boolean;act:(f:()=>Promise<void>)=>Promise<void>;onLogin:()=>Promise<void>;setMessage:(s:string)=>void}){
 const [mode,setMode]=useState('password'),[step,setStep]=useState<string>(initialPage||'login'),[verification,setVerification]=useState(''),[challenge,setChallenge]=useState(''),[resetToken,setResetToken]=useState(''),[recoverable,setRecoverable]=useState(false),[sentEmail,setSentEmail]=useState('');const form=useRef<HTMLFormElement>(null);const captcha=useCaptcha();
 useEffect(()=>{const params=new URLSearchParams(location.search);if(params.get('registered')==='1')setMessage('账号已创建，请登录');if(params.get('mfa')==='1')setStep('mfa');else if(params.get('recover')==='1')setStep('forgot');const match=location.hash.match(/^#reset=([0-9a-f]{64})$/);if(match){setResetToken(match[1]);setStep('reset');history.replaceState(null,'',location.pathname)}void api('/auth/v1/recovery').then(v=>setRecoverable(v.enabled)).catch(()=>{})},[]);
 function change(next:string){setStep(next);setChallenge('');setVerification('');setSentEmail('');captcha.reset();setMessage('');form.current?.reset()}
 const needsEmailProof=(step==='register'||(step==='login'&&mode==='email'))&&!verification;
 const action=needsEmailProof?'email_code':step==='register'?'register':step==='forgot'?'forgot_password':step==='reset'?'reset_password':mode==='email'?'email_login':'login';
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const fields=new FormData(e.currentTarget);await act(async()=>{try{
  let result:any;
  if((step==='register'||step==='reset')&&!validPassword(String(fields.get('password')||'')))throw new Error('密码须为 8–24 个字符');
  if(step==='mfa')result=await api('/account/v1/mfa-login','POST',{challenge_id:challenge,totp_code:fields.get('totp_code')});
  else if(step==='forgot'){await api('/auth/v1/forgot-password','POST',{email:fields.get('email'),turnstile_token:captcha.token});setMessage('若邮箱匹配可用账号，将发送重置链接。请检查收件箱。');return}
  else if(step==='reset'){await api('/auth/v1/reset-password','POST',{token:resetToken,password:fields.get('password'),totp_code:fields.get('totp_code'),turnstile_token:captcha.token});setResetToken('');change('login');setMessage('密码已重置，请重新登录');return}
  else if(step==='register'){if(String(fields.get('email'))!==sentEmail)throw new Error('邮箱已变化，请重新获取验证码');await api('/account/v1/register','POST',{username:fields.get('username'),nickname:fields.get('nickname'),email:fields.get('email'),password:fields.get('password'),code:fields.get('code'),verification_id:verification,turnstile_token:captcha.token});location.assign('/login'+returnQuery()+(returnQuery()?'&':'?')+'registered=1');return}
  else if(mode==='email'){if(String(fields.get('email'))!==sentEmail)throw new Error('邮箱已变化，请重新获取验证码');result=await api('/account/v1/email-login','POST',{verification_id:verification,code:fields.get('code'),turnstile_token:captcha.token})}
  else result=await api('/auth/v1/login','POST',{username:fields.get('username'),password:fields.get('password'),turnstile_token:captcha.token});
  if(result.mfa_required){setChallenge(result.challenge_id);setStep('mfa');form.current?.reset();return}form.current?.reset();await onLogin();const destination=new URLSearchParams(location.search).get('return');if(destination==='home')location.assign('/');else if(destination==='guide')location.assign('/guide');else if(destination==='docs')location.assign('/docs');else if(destination==='playground')location.assign('/playground');else if(destination==='admin')location.assign('/account');
 }finally{captcha.reset()}})}
 async function sendCode(){await act(async()=>{try{const email=form.current?.querySelector<HTMLInputElement>('[name=email]')?.value||'';if(!email)throw new Error('请填写邮箱');const fields=form.current?.querySelectorAll<HTMLInputElement>('input[name=email],input[name=email_local]');if(fields&&[...fields].some(input=>input.type!=='hidden'&&!input.reportValidity()))return;const result=await api('/account/v1/send-code','POST',{email,purpose:step==='register'?'register':'email-login',turnstile_token:captcha.token});setVerification(result.verification_id);setSentEmail(email);setMessage(result.message)}finally{captcha.reset()}})}
 async function oauth(provider:string){await act(async()=>{const destination=new URLSearchParams(location.search).get('return')||'';const result=await api('/account/v1/oauth/'+provider+'/start','POST',{return_to:destination});const url=new URL(result.url);if(url.protocol!=='https:'||!['github.com','accounts.google.com','oauth.telegram.org'].includes(url.hostname))throw new Error('授权地址不可用');location.assign(result.url)})}
 async function passkeyLogin(){await act(async()=>{await (await passkeyTools()).ceremony('login');await onLogin();const target=new URLSearchParams(location.search).get('return');location.assign(({home:'/',docs:'/docs',guide:'/guide',playground:'/playground'} as Record<string,string>)[target||'']||'/account')})}
 const returnQuery=()=>{const target=new URLSearchParams(location.search).get('return');return target&&['home','docs','guide','playground','admin'].includes(target)?'?return='+encodeURIComponent(target):''};
 const title={login:'登录账号',register:'创建账号',mfa:'双重验证',forgot:'找回密码',reset:'重置密码'}[step];
 return <section className="account-auth"><div className="account-auth-intro"><ShieldCheck size={36}/><h1>每次调用，清晰可控</h1><p>管理余额、套餐、调用记录与账号安全。</p><ul><li>费用与余额流水有据可查</li><li>按小时、每日、每月掌握额度</li><li>前台与后台共享登录状态</li></ul></div><div className="account-auth-form"><nav className="account-auth-nav" aria-label="账号访问"><a href={'/login'+returnQuery()} aria-current={step==='login'?'page':undefined}>登录</a><a href={'/register'+returnQuery()} aria-current={step==='register'?'page':undefined}>创建账号</a></nav><h2>{title}</h2>{step==='login'&&options.email_login&&<div className="account-mode"><button disabled={busy} aria-pressed={mode==='password'} onClick={()=>{setMode('password');change('login')}}>密码登录</button><button disabled={busy} aria-pressed={mode==='email'} onClick={()=>{setMode('email');change('login')}}>邮箱验证码</button></div>}
 {step==='register'&&!options.registration?<section className="registration-unavailable"><h3>{options.registration_enabled?'注册暂不可用':'当前未开放注册'}</h3><p>{options.registration_enabled&&!options.mail_available?'网站邮件服务尚未配置，暂时无法验证注册邮箱。':'请等待管理员开放注册，已有账号可以继续登录。'}</p><a className="account-primary" href={'/login'+returnQuery()}>返回登录</a></section>:<form ref={form} onSubmit={submit} key={step+mode} onChange={e=>{if(['email','email_local','email_domain'].includes((e.target as HTMLInputElement).name)&&verification){setVerification('');setSentEmail('');captcha.reset()}}}>
  {step==='mfa'?<><p>输入验证器动态码，或一个未使用的恢复码。验证失败后须重新开始登录。</p><label>动态码或恢复码<input name="totp_code" autoComplete="one-time-code" maxLength={64} required/></label></>:<>
   {(step==='register'||(step==='login'&&mode==='password'))&&<label>{step==='login'?'用户名或邮箱':'用户名'}<input name="username" autoComplete="username" minLength={step==='register'?3:undefined} maxLength={step==='register'?20:254} required pattern={step==='register'?'[a-zA-Z0-9]{3,20}':undefined}/>{step==='register'&&<small>3–20 位字母或数字，不能与其他用户重复。</small>}</label>}
   {step==='register'&&<label>昵称<input name="nickname" maxLength={64} required/></label>}
   {(step==='register'||step==='forgot'||(step==='login'&&mode==='email'))&&<EmailField key={step+mode} domains={step==='forgot'?[]:options.allowed_email_domains} disabled={busy}/>}
   {(step==='register'||(step==='login'&&mode==='email'))&&<div className="email-code-row"><label>邮箱验证码<input name="code" autoComplete="one-time-code" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} required disabled={busy}/></label><button type="button" className="send-code-button" disabled={busy||!!options.turnstile&&!captcha.token} onClick={()=>void sendCode()}>发送</button></div>}
   {(step==='register'||step==='reset'||(step==='login'&&mode==='password'))&&<label>{step==='reset'?'新密码':'密码'}<input name="password" type="password" autoComplete={step==='login'?'current-password':'new-password'} maxLength={step==='login'?72:24} required/><small>{step==='login'?'请输入账号密码。':'8–24 个字符，可使用符号。'}</small></label>}
   {step==='reset'&&<label>动态码或恢复码（已启用双重验证时必填）<input name="totp_code" autoComplete="one-time-code" maxLength={64}/></label>}
   <Captcha options={options} action={action} control={captcha}/>
  </>}
  <div className={'auth-submit-row'+(step==='login'&&mode==='password'&&recoverable?' with-recovery':'')}><button className="account-primary auth-submit-primary" disabled={busy||step!=='mfa'&&((!!options.turnstile&&!captcha.token)||needsEmailProof)}>{busy?'正在处理…':title}</button>{step==='login'&&mode==='password'&&recoverable&&<button type="button" className="auth-recovery-button" disabled={busy} onClick={()=>change('forgot')}>忘记密码</button>}</div>
 </form>}
 {step==='login'&&<button type="button" className="passkey-login-button secondary" disabled={busy} onClick={()=>void passkeyLogin()}><KeyRound size={18}/><span>使用通行密钥登录</span></button>}
 {(step==='login'||step==='register')&&(options.github||options.google||options.telegram)&&<><div className="account-social">{options.github&&<button type="button" className="provider-icon-button github-provider" aria-label={step==='register'?'使用 GitHub 账号创建':'使用 GitHub 账号登录'} title={step==='register'?'使用 GitHub 账号创建':'使用 GitHub 账号登录'} disabled={busy} onClick={()=>void oauth('github')}><ProviderIcon provider="github"/><span>{step==='register'?'GitHub 创建':'GitHub 登录'}</span></button>}{options.google&&<button type="button" className="provider-icon-button" aria-label={step==='register'?'使用 Google 账号创建':'使用 Google 账号登录'} title={step==='register'?'使用 Google 账号创建':'使用 Google 账号登录'} disabled={busy} onClick={()=>void oauth('google')}><ProviderIcon provider="google"/><span>{step==='register'?'Google 创建':'Google 登录'}</span></button>}{options.telegram&&<button type="button" className="provider-icon-button" aria-label={step==='register'?'使用 Telegram 账号创建':'使用 Telegram 账号登录'} title={step==='register'?'使用 Telegram 账号创建':'使用 Telegram 账号登录'} disabled={busy} onClick={()=>void oauth('telegram')}><ProviderIcon provider="telegram"/><span>{step==='register'?'Telegram 创建':'Telegram 登录'}</span></button>}</div></>}
 {step==='register'&&options.telegram&&<p className="account-note">首次使用 Telegram 登录后，须绑定并验证邮箱才能完成注册。</p>}
 {step!=='login'&&step!=='register'&&<div className="account-auth-links"><a href={'/login'+returnQuery()}>返回登录</a></div>}
 </div></section>;
}
function Table({headers,rows,empty}:{headers:string[];rows:ReactNode[][];empty:string}){return rows.length?<div className="account-table"><table><thead><tr>{headers.map(header=><th key={header} scope="col">{header}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{cell}</td>)}</tr>)}</tbody></table></div>:<p className="account-empty">{empty}</p>}
function Plans({canPurchase,plans,wallet,busy,act,reload,setMessage}:{canPurchase:boolean;plans:Plan[];wallet:WalletData|null;busy:boolean;act:(f:()=>Promise<void>)=>Promise<void>;reload:()=>Promise<void>;setMessage:(s:string)=>void}){
 const [scheduled,setScheduled]=useState<Row[]>([]);useEffect(()=>{let active=true;void api<Row[]>('/account/v1/subscriptions').then(v=>{if(active)setScheduled(v.filter(s=>new Date(s.starts_at)>new Date()))}).catch(()=>{});return()=>{active=false}},[wallet]);const [purchase,setPurchase]=useState<{plan:Plan;operation:string}|null>(null);const current=wallet?.subscription;
 return <div className="account-plans-page"><PlanUsage wallet={wallet}/><section className="account-plan-summary"><div><span>当前套餐</span><h2>{current?.plan_name||'按次计费'}</h2><p>{current?'有效至 '+date(current.expires_at):'尚未绑定套餐，按接口公示价格调用。'}</p></div><div><span>可用余额</span><strong>¥ {money((wallet?.wallet.balance_micros||0)-(wallet?.wallet.held_micros||0))}</strong><small>购买前请确认余额；续购将在当前套餐到期后生效。</small></div></section><div className="account-panel-heading"><div><h2>可选套餐</h2><p>有效套餐覆盖成功调用的费用。额度用尽不会自动改为余额扣费。</p></div><span className="account-status">{plans.length} 个套餐</span></div>{scheduled.length>0&&<section className="account-panel renewal-panel"><h2>待生效续订</h2>{scheduled.map(s=><p key={s.id}>{s.plan_name} · {date(s.starts_at)} 开始，{date(s.expires_at)} 到期</p>)}</section>}<div className="account-plan-grid">{plans.map(plan=><section className="account-plan-card" key={plan.id}><div className="account-plan-top"><div><h2>{plan.name}</h2><p>{plan.description||'适用于日常接口调用'}</p></div><span className="plan-duration">有效期 {plan.days} 天</span></div><div className="account-plan-price"><strong>¥ {money(plan.price_micros)}</strong><small>/ {plan.days} 天</small></div><ul className="account-plan-limits">{[['每小时',plan.hourly],['每日',plan.daily],['每月',plan.monthly]].map(([title,value])=><li key={title}><span>{title}</span><strong>{value?Number(value).toLocaleString('zh-CN'):'不限'}</strong><small>{value?'次调用':'不限次数'}</small></li>)}</ul><button disabled={!canPurchase||busy} onClick={()=>setPurchase({plan,operation:crypto.randomUUID()})}>{current?.plan_id===plan.id?'续订此套餐':'购买套餐'}</button></section>)}</div>{!plans.length&&<section className="account-panel"><p>暂未提供可购买套餐。管理员可以直接绑定套餐，或使用余额按次调用。</p></section>}
 <Dialog open={!!purchase} title="确认购买套餐" onClose={()=>{if(!busy)setPurchase(null)}}><p>购买 {purchase?.plan.name} 将从余额扣除 ¥ {money(purchase?.plan.price_micros||0)}。请确认额度和有效期。</p><p>若请求超时，请使用“重试此购买”，不要重复新建订单。</p><div className="account-actions"><button disabled={busy} onClick={()=>setPurchase(null)}>取消</button><button disabled={busy} onClick={()=>void act(async()=>{if(!purchase)return;await api('/account/v1/subscription','POST',{plan_id:purchase.plan.id,operation_id:purchase.operation,confirm:true});setPurchase(null);await reload();setMessage('套餐已购买；当前套餐未到期时，续订将在到期后生效。')})}>确认 / 重试此购买</button></div></Dialog></div>;
}

function Keys({rows,options,profile,busy,act,reload,secret,setSecret}:{rows:Row[];options:Options;profile:Profile;busy:boolean;act:(f:()=>Promise<void>)=>Promise<void>;reload:()=>Promise<void>;secret:string;setSecret:(s:string)=>void}){
 const [target,setTarget]=useState<Row|null>(null),[operation,setOperation]=useState<'create'|'reveal'|'revoke'|'rotate'|'policy'>('create'),[open,setOpen]=useState(false),[visibleKey,setVisibleKey]=useState(''),[copied,setCopied]=useState(false);const manageCaptcha=useCaptcha();
 const canKey=(code:string)=>profile.permissions.includes('*')||profile.permissions.includes(code);
 const begin=(key:Row|null,kind:'create'|'reveal'|'revoke'|'rotate'|'policy')=>{setSecret('');setVisibleKey('');setCopied(false);setTarget(key);setOperation(kind);manageCaptcha.reset();setOpen(true)};
 const close=()=>{if(busy)return;setOpen(false);setTarget(null);setVisibleKey('');setSecret('');setCopied(false)};
 return <section className="account-panel"><div className="account-panel-heading"><div><h2>我的调用凭据</h2><p>管理用于程序调用的凭据。密钥加密保存，验证密码后可以再次查看，请妥善保管。</p></div><button type="button" disabled={busy||!canKey('account.keys.write')} onClick={()=>begin(null,'create')}>新建调用凭据</button></div>
 <Table headers={['名称 / 前缀','创建 / 到期时间','状态','操作']} rows={rows.map(key=>[<><strong>{key.name}</strong><br/><code>{key.prefix}</code></>,<><span>{date(key.created_at)}</span><br/><small>{key.expires_at?'到期 '+date(key.expires_at):'长期有效'}</small></>,<span className={'account-status'+(key.revoked?' error':'')}>{key.revoked?'已吊销':key.expires_at&&new Date(key.expires_at).getTime()<Date.now()?'已过期':'可使用'}</span>,<div className="account-actions"><button disabled={busy||key.revoked||!key.api_key_available||!canKey('account.keys.reveal')} onClick={()=>begin(key,'reveal')}>查看密钥</button><button disabled={busy||key.revoked||!canKey('account.keys.write')} onClick={()=>begin(key,'rotate')}>重置密钥</button><button disabled={busy||key.revoked||!canKey('account.keys.write')} onClick={()=>begin(key,'policy')}>IP 限制</button><button className="danger" disabled={busy||key.revoked||!canKey('account.keys.write')} onClick={()=>begin(key,'revoke')}>吊销</button></div>])} empty="暂无调用凭据，点击右上角新建。"/>
 <Dialog open={open} title={operation==='policy'?'限制密钥使用 IP':operation==='create'?'新建调用凭据':operation==='reveal'?'查看调用凭据密钥':operation==='rotate'?'重置调用密钥':'吊销调用凭据'} onClose={close}>{visibleKey?<><p>密钥只在当前窗口展示。关闭后会隐藏，之后可重新验证查看。</p><div className="account-secret"><code>{visibleKey}</code></div><div className="account-actions"><button type="button" onClick={()=>void navigator.clipboard.writeText(visibleKey).then(()=>setCopied(true)).catch(()=>setCopied(false))}>{copied?'已复制':'复制密钥'}</button><button type="button" onClick={close}>关闭并隐藏密钥</button></div></>:<><p>{operation==='policy'?'设置此密钥允许的调用来源。保存后，不在范围内的来源会被拒绝；留空表示不限制。':operation==='create'?'创建自己的程序调用凭据。':operation==='reveal'?'请验证当前密码后查看密钥。':operation==='rotate'?'重置后，旧密钥立即失效，请更新使用此密钥的程序。':'吊销后，使用此凭据的程序将无法调用。'} {target?.name}</p><form key={(target?.id||'new')+operation} onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void act(async()=>{try{if(operation==='create'){const result=await api('/account/v1/keys','POST',{key_name:f.get('key_name'),allowed_ip_ranges:String(f.get('allowed_ip_ranges')||'').split(/[\s,]+/).filter(Boolean),expires_at:f.get('expires_at')?siteDateInputToISO(String(f.get('expires_at'))):null,...stepup(f,manageCaptcha.token)});setVisibleKey(result.api_key);setSecret('');await reload()}else if(operation==='reveal'){const result=await api('/account/v1/keys/'+encodeURIComponent(target!.id)+'/reveal','POST',stepup(f,manageCaptcha.token));if(typeof result.api_key!=='string'||!result.api_key)throw new Error('密钥读取失败，请重试');setVisibleKey(result.api_key)}else if(operation==='rotate'){const result=await api('/account/v1/keys/'+encodeURIComponent(target!.id)+'/rotate','POST',{confirm:true,...stepup(f,manageCaptcha.token)});setVisibleKey(result.api_key);await reload()}else if(operation==='policy'){await api('/account/v1/keys/'+encodeURIComponent(target!.id)+'/ip-policy','PUT',{confirm:true,allowed_ip_ranges:String(f.get('allowed_ip_ranges')||'').split(/[\s,]+/).filter(Boolean),...stepup(f,manageCaptcha.token)});setOpen(false);setTarget(null);await reload()}else{await api('/account/v1/keys/'+encodeURIComponent(target!.id),'DELETE',stepup(f,manageCaptcha.token));setOpen(false);setTarget(null);await reload()}}finally{manageCaptcha.reset()}})}}>{operation==='create'&&<><label>凭据名称<input name="key_name" maxLength={64} required autoComplete="off"/></label><label>到期时间（留空表示长期有效）<input name="expires_at" type="datetime-local"/></label></>}{(operation==='create'||operation==='policy')&&<label>允许的 IP 地址或 CIDR 地址段<textarea name="allowed_ip_ranges" rows={4} maxLength={4096} defaultValue={(target?.allowed_ip_ranges||[]).join('\n')} placeholder={"203.0.113.10\n203.0.113.0/24\n2001:db8::/48"}/><small>每行一项，最多 32 项。单个地址可填 203.0.113.10 或 2001:db8::1；网段可填 203.0.113.0/24 或 2001:db8::/48。不要填写端口、网址或域名。仅匹配调用程序的公网出口地址；留空不限制。示例地址只表示格式，请替换为实际出口地址。</small></label>}<Fields totp={profile.totp_enabled}/><div className="account-actions"><button type="button" disabled={busy} onClick={close}>取消</button><button disabled={busy}>{operation==='policy'?'保存 IP 限制':operation==='create'?'创建调用凭据':operation==='reveal'?'验证并查看密钥':operation==='rotate'?'确认重置密钥':'确认吊销'}</button></div></form></>}</Dialog></section>;
}

function Sessions({rows,profile,options,busy,act,reload,refresh}:{rows:Row[];profile:Profile;options:Options;busy:boolean;act:(f:()=>Promise<void>)=>Promise<void>;reload:()=>Promise<void>;refresh:()=>Promise<void>}){
 const [target,setTarget]=useState<Row|null>(null),[people,setPeople]=useState<Row[]>([]),[selected,setSelected]=useState(profile.uid),[remote,setRemote]=useState<Row[]|null>(null),[error,setError]=useState('');const captcha=useCaptcha();const administrator=profile.permissions.includes('*');
 useEffect(()=>{if(administrator)void api<Row[]>('/account/v1/session-users').then(setPeople).catch(e=>setError(e.message))},[administrator]);
 const load=async(id:string)=>{setError('');try{setRemote(await api('/account/v1/sessions?user_id='+encodeURIComponent(id)))}catch(e){setError(e instanceof Error?e.message:'会话读取失败')}};
 const list=remote||rows;return <>{administrator&&<form onSubmit={e=>e.preventDefault()}><label>管理用户的登录会话<select value={selected} onChange={e=>{setSelected(e.target.value);void load(e.target.value)}}>{people.map(u=><option key={u.id} value={u.id}>{u.nickname||u.username}</option>)}</select></label></form>}<p>退出会话后，该设备须重新登录。个人会话和管理员全站会话管理统一在此处。公网地址优先显示最近活动记录。旧会话未记录真实地址时，该设备再次访问或重新登录后会更新。</p>{error&&<p className="account-message" role="alert">{error}</p>}<Table headers={['设备','公网 IP','最近活动','有效期','状态','操作']} rows={list.map(s=>[s.device||'未知设备',s.public_ip||s.last_ip||s.login_ip||'未记录',date(s.last_seen_at),date(s.expires_at),s.current?'当前设备':'其他设备',<button disabled={busy} onClick={()=>{captcha.reset();setTarget(s)}}>退出会话</button>])} empty="没有可用会话。"/>
 <Dialog open={!!target} title="退出登录会话" onClose={()=>{if(!busy)setTarget(null)}}><p>确认退出 {target?.device||'此设备'}？</p><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void act(async()=>{try{await api('/account/v1/sessions/'+encodeURIComponent(target!.id),'DELETE',{confirm:true,user_id:selected,...(selected!==profile.uid?stepup(f,captcha.token):{})});setTarget(null);await refresh();if(selected===profile.uid){await reload();setRemote(null)}else await load(selected);broadcast()}finally{captcha.reset()}})}}>{selected!==profile.uid&&<><Fields totp={profile.totp_enabled}/></>}<div className="account-actions"><button type="button" disabled={busy} onClick={()=>setTarget(null)}>取消</button><button disabled={busy}>确认退出</button></div></form></Dialog></>;
}

function Security({profile,options,busy,act,refresh,setMessage,setRecovery}:{profile:Profile;options:Options;busy:boolean;act:(f:()=>Promise<void>)=>Promise<void>;refresh:()=>Promise<void>;setMessage:(s:string)=>void;setRecovery:(s:string[])=>void}){
 const [operation,setOperation]=useState<'username'|'email'|'password'|'totp'|'identity'|null>(null),[provider,setProvider]=useState('github'),[setup,setSetup]=useState<{secret:string;uri:string}|null>(null),[identities,setIdentities]=useState<string[]>([]),[email,setEmail]=useState(''),[emailProof,setEmailProof]=useState(''),[sentEmail,setSentEmail]=useState('');
 const captcha=useCaptcha();const form=useRef<HTMLFormElement>(null);const confirmationMethod=profile.confirmation_method||'password';
 useEffect(()=>{let active=true;void api<string[]>('/account/v1/identities').then(v=>{if(active)setIdentities(v)}).catch(()=>{});return()=>{active=false}},[profile.uid]);
 const begin=(kind:typeof operation,p='github')=>{setOperation(kind);setProvider(p);setSetup(null);setEmail('');setEmailProof('');setSentEmail('');captcha.reset()};
 const close=()=>{if(busy)return;setOperation(null);setSetup(null);setEmailProof('');captcha.reset()};
 const titles={username:'修改用户名',email:'修改邮箱',password:'修改密码',totp:'验证器双重验证',identity:'管理第三方登录'};
 async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();const fields=new FormData(e.currentTarget);await act(async()=>{try{
  const proof=stepup(fields,captcha.token);
  if(operation==='totp'){
   const result=await api('/account/v1/totp','POST',{purpose:profile.totp_enabled?'disable':setup?'enable':'begin',...proof});
   if(result.secret){setSetup(result);return};setSetup(null);setRecovery(result.recovery_codes||[]);
  }else if(operation==='identity'){
   if(identities.includes(provider)){await api('/account/v1/identities/'+provider,'DELETE',proof);setIdentities(await api('/account/v1/identities'));setOperation(null);setMessage('授权账号已解绑');return}
   const result=await api('/account/v1/oauth/'+provider+'/start','POST',{purpose:'link',...proof});const url=new URL(result.url);if(url.protocol!=='https:'||!['github.com','accounts.google.com','oauth.telegram.org'].includes(url.hostname))throw Error('授权地址不可用');location.assign(result.url);return;
  }else{
   const value:any={...proof};
   if(operation==='username'){const username=String(fields.get('username')||'');if(username!==profile.user.username&&!/^[a-zA-Z0-9]{3,20}$/.test(username))throw Error('用户名须为 3–20 位字母或数字');value.username=username;}
   if(operation==='email'){if(!emailProof||email!==sentEmail)throw Error('请先获取新邮箱验证码');value.email=email;value.verification_id=emailProof;value.verification_code=fields.get('code')}
   if(operation==='password'){const password=String(fields.get('password')||'');if(!validPassword(password))throw Error('新密码须为 8–24 个字符');if(password!==fields.get('password_confirm'))throw Error('两次新密码不一致');value.password=password}
   await api('/auth/v1/me','PUT',value);
  }
  setOperation(null);broadcast();await refresh();setMessage('安全设置已更新，请重新登录');
 }finally{captcha.reset()}})}
 return <div className="security-dashboard">
  <section className="account-panel"><div className="account-panel-heading"><div><h2>账号登录信息</h2><p>修改后会退出已有登录会话。</p></div></div><div className="security-setting-row"><div><strong>用户名</strong><span>{profile.user.username}</span></div><button type="button" disabled={busy} onClick={()=>begin('username')}>修改用户名</button></div><div className="security-setting-row"><div><strong>邮箱</strong><span>{profile.user.email||'尚未绑定'}</span></div><button type="button" disabled={busy} onClick={()=>begin('email')}>修改邮箱</button></div><div className="security-setting-row"><div><strong>登录密码</strong><span>定期更新密码，请勿与其他网站共用。</span></div><button type="button" disabled={busy} onClick={()=>begin('password')}>修改密码</button></div></section>
  <section className="account-panel"><div className="account-panel-heading"><div><h2>验证器双重验证</h2><p>使用动态码或恢复码保护登录与个人关键操作。</p></div><span className={'account-status'+(profile.totp_enabled?'':' neutral')}>{profile.totp_enabled?'已启用':'未启用'}</span></div><p className="security-description">{profile.totp_enabled?'关闭双重验证需确认身份，完成后已有会话会退出。':'绑定兼容 TOTP 的验证器应用，开启第二重保护。'}</p><ul className="security-tips"><li>验证码每 30 秒更新一次。</li><li>恢复码仅显示一次，请离线保存。</li><li>关键操作可使用密码及动态码，或通行密钥确认。</li></ul><div className="account-actions"><button type="button" disabled={busy} onClick={()=>begin('totp')}>{profile.totp_enabled?'关闭双重验证':'设置双重验证'}</button></div></section>
  {(options.github||options.google||options.telegram||identities.length>0)&&<section className="account-panel security-identities"><h2>第三方登录</h2><p>提供 GitHub、Google 和 Telegram 授权登录，不根据相同邮箱自动合并账号。</p>{['github','google','telegram'].filter(p=>identities.includes(p)||options[p as 'github'|'google'|'telegram']).map(p=><div className="security-setting-row" key={p}><div><strong>{p==='github'?'GitHub':p==='google'?'Google':'Telegram'}</strong><span>{identities.includes(p)?'已绑定':'尚未绑定'}</span></div><button type="button" disabled={busy} onClick={()=>begin('identity',p)}>{identities.includes(p)?'解绑':'绑定'}</button></div>)}<p className="account-note">首次通过授权登录的用户，可通过找回密码设置本地密码，再管理绑定。</p></section>}
  <ConfirmationPreference profile={profile} busy={busy} act={act} refresh={refresh} setMessage={setMessage}/>
  <PasskeyManagement profile={profile} busy={busy} act={act} setMessage={setMessage}/>
  <Dialog open={!!operation} title={operation?titles[operation]:''} onClose={close}><p>请验证当前账号。修改登录信息后须重新登录。</p><form ref={form} className="security-operation-form" onSubmit={save}>
   {operation==='username'&&<label>新用户名<input name="username" defaultValue={profile.user.username} minLength={3} maxLength={Math.max(20,profile.user.username.length)} autoComplete="username" required/><small>新用户名须为 3–20 位字母或数字，不能重复。</small></label>}
   {operation==='email'&&<><label>新邮箱<input value={email} type="email" maxLength={254} autoComplete="email" required onChange={e=>{setEmail(e.target.value);setEmailProof('')}}/></label><div className="email-code-row"><label>新邮箱验证码<input name="code" autoComplete="one-time-code" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} required/></label><button type="button" disabled={busy||!email||email===profile.user.email} onClick={()=>void act(async()=>{const result=await api('/account/v1/send-code','POST',{email,purpose:'change-email'});setEmailProof(result.verification_id);setSentEmail(email);setMessage('验证码已发送至新邮箱')})}>发送验证码</button></div></>}
   {operation==='password'&&<><label>新密码<input name="password" type="password" autoComplete="new-password" maxLength={24} required/><small>8–24 个字符。</small></label><label>确认新密码<input name="password_confirm" type="password" autoComplete="new-password" maxLength={24} required/></label></>}
   {operation==='totp'&&setup&&<div className="account-secret"><h3>在验证器中添加账号</h3><code>{setup.secret}</code><p>账号：{profile.user.username}。6 位数字，每 30 秒更新。绑定密钥不得分享。</p></div>}
   <Fields totp={profile.totp_enabled}/>{operation==='totp'&&setup&&!profile.totp_enabled&&<label>验证器动态码<input name="totp_code" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} autoComplete="one-time-code" required/></label>}
   {operation==='password'&&confirmationMethod!=='passkey'&&<Captcha options={options} action="password_change" control={captcha}/>}
   <div className="account-actions"><button type="button" disabled={busy} onClick={close}>取消</button><button disabled={busy||(operation==='password'&&confirmationMethod!=='passkey'&&!!options.turnstile&&!captcha.token)}>{operation==='totp'&&!profile.totp_enabled&&!setup?'获取绑定信息':operation==='identity'?(identities.includes(provider)?'确认解绑':'验证并前往授权'):'验证并保存'}</button></div>
  </form></Dialog>
 </div>;
}

function VerifyEmail({options,email,busy,act,refresh,setMessage}:{options:Options;email:string;busy:boolean;act:(f:()=>Promise<void>)=>Promise<void>;refresh:()=>Promise<void>;setMessage:(s:string)=>void}){const [proof,setProof]=useState('');return <form className="verify-email-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void act(async()=>{await api('/account/v1/verify-email','POST',{verification_id:proof,code:f.get('code')});await refresh();setMessage('邮箱已验证')})}}><p className="account-note">验证码将发送至 {email}。</p><div className="email-code-row"><label>邮箱验证码<input name="code" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" maxLength={6} required/></label><button type="button" disabled={busy} onClick={()=>void act(async()=>{const result=await api('/account/v1/send-code','POST',{email,purpose:'verify-email'});setProof(result.verification_id);setMessage('验证码已发送')})}>发送验证码</button></div><div className="account-actions"><button disabled={busy||!proof}>验证邮箱</button></div></form>}

function BasicProfile({profile,options,busy,act,refresh,setMessage}:{profile:Profile;options:Options;busy:boolean;act:(f:()=>Promise<void>)=>Promise<void>;refresh:()=>Promise<void>;setMessage:(s:string)=>void}){return <div className="account-basic-grid"><section className="account-panel"><div className="account-panel-heading"><div><h2>个人展示资料</h2><p>昵称用于展示，不影响登录用户名。</p></div></div><form className="account-basic-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void act(async()=>{await api('/account/v1/basic','PUT',{nickname:f.get('nickname'),time_zone:f.get('time_zone')});await refresh();setMessage('基础资料已保存')})}}><label>昵称<input name="nickname" defaultValue={profile.nickname||profile.user.username} maxLength={64} required autoComplete="nickname"/></label><PersonalTimeZone value={profile.personal_time_zone||''}/><div className="account-actions"><button disabled={busy}>保存资料</button></div></form><dl className="account-info-list"><div><dt>用户名</dt><dd>{profile.user.username}</dd></div><div><dt>唯一 UID</dt><dd><code>{profile.uid}</code></dd></div><div><dt>邮箱</dt><dd>{profile.user.email||'尚未绑定'} <span className="account-status">{profile.email_verified?'已验证':'未验证'}</span></dd></div></dl><p className="account-note">用户名、邮箱或密码修改，请进入“账号安全”。UID 自动生成，不可修改。</p></section><section className="account-panel"><h2>邮箱验证</h2><p>验证邮箱后可用于找回密码和接收安全通知。</p>{profile.email_verified?<div className="account-verified"><ShieldCheck size={30}/><strong>当前邮箱已验证</strong><span>{profile.user.email}</span></div>:profile.user.email?<VerifyEmail options={options} email={profile.user.email} busy={busy} act={act} refresh={refresh} setMessage={setMessage}/>:<p className="account-note">请先在账号安全中绑定邮箱。</p>}</section></div>}

function PlanUsage({wallet}:{wallet:WalletData|null}){const sub=wallet?.subscription;if(!sub)return <section className="account-panel plan-usage"><h2>套餐用量</h2><p>当前没有生效套餐，接口按公示价格计费。</p></section>;return <section className="account-panel plan-usage"><div className="account-panel-heading"><div><h2>套餐用量</h2><p>{sub.plan_name}</p></div><span className="plan-duration">有效至 {date(sub.expires_at)}</span></div><div className="usage-grid">{(['hourly','daily','monthly'] as const).map((key,i)=>{const used=wallet?.usage?.[key]||0,limit=sub[key];return <section key={key}><span>{['本小时','今日','本月'][i]}</span><strong>{used.toLocaleString()} <small>/ {limit?limit.toLocaleString():'不限'}</small></strong><progress value={limit?Math.min(used,limit):0} max={limit||1}/><p>{limit?'剩余 '+Math.max(0,limit-used).toLocaleString()+' 次':'不限次数'}</p></section>})}</div></section>}
function Redeem({busy,act,reload,setMessage}:{busy:boolean;act:(fn:()=>Promise<void>)=>Promise<void>;reload:()=>Promise<void>;setMessage:(s:string)=>void}){const [code,setCode]=useState(''),[confirm,setConfirm]=useState(false);return <section className="account-panel redeem-panel"><h2>兑换卡密</h2><p>余额卡密增加可用余额；套餐卡密激活套餐，已有套餐时排入续订。卡密只能使用一次。</p><form onSubmit={e=>{e.preventDefault();setConfirm(true)}}><label>卡密<input value={code} onChange={e=>setCode(e.target.value)} maxLength={128} required autoComplete="off"/></label><button disabled={busy||!code.trim()}>确认兑换</button></form><Dialog open={confirm} title="确认兑换卡密" onClose={()=>{if(!busy)setConfirm(false)}}><p>兑换至当前账号后不可转移，请确认账号正确。</p><div className="account-actions"><button disabled={busy} onClick={()=>setConfirm(false)}>取消</button><button disabled={busy} onClick={()=>void act(async()=>{await api('/account/v1/redeem','POST',{code:code.trim(),confirm:true});setConfirm(false);setCode('');await reload();setMessage('卡密兑换成功，请在套餐或余额流水中查看。')})}>确认兑换</button></div></Dialog></section>}

function PersonalTimeZone({value}:{value:string}){
 const choices=[['Asia/Shanghai','中国大陆 · 北京时间'],['Asia/Hong_Kong','香港时间'],['Asia/Taipei','台北时间'],['Asia/Tokyo','日本时间'],['Asia/Seoul','韩国时间'],['Asia/Singapore','新加坡时间'],['Asia/Dubai','迪拜时间'],['Asia/Kolkata','印度时间'],['Europe/London','伦敦时间'],['Europe/Berlin','柏林时间'],['Europe/Paris','巴黎时间'],['America/New_York','纽约时间'],['America/Los_Angeles','洛杉矶时间'],['America/Toronto','多伦多时间'],['America/Sao_Paulo','圣保罗时间'],['Australia/Sydney','悉尼时间'],['Pacific/Auckland','奥克兰时间'],['UTC','协调世界时']];
 return <label>个人时区<select name="time_zone" defaultValue={value}><option value="">跟随网站默认</option>{value&&!choices.some(([id])=>id===value)&&<option value={value}>{value}</option>}{choices.map(([id,label])=><option value={id} key={id}>{label}</option>)}</select><small>时间按个人偏好显示，不改变套餐额度周期。</small></label>
}

function PasskeyManagement({profile,busy,act,setMessage}:{profile:Profile;busy:boolean;act:(f:()=>Promise<void>)=>Promise<void>;setMessage:(s:string)=>void}){
 const [keys,setKeys]=useState<Row[]>([]),[operation,setOperation]=useState<'create'|'delete'|null>(null),[selected,setSelected]=useState<Row|null>(null);
 const load=()=>api<{items:Row[]}>('/account/v1/passkeys').then(v=>setKeys(v.items));useEffect(()=>{void load().catch(()=>{})},[profile.uid]);
 return <section className="account-panel security-passkeys"><div className="security-card-heading"><div><h2>通行密钥</h2><p>使用设备锁屏验证、指纹或安全密钥登录与确认敏感操作。</p></div><span className="account-status neutral">{keys.length} 个</span></div><p className="account-note">密码不会保存到通行密钥中。更换网站域名后，需要在新域名重新添加。</p><div className="passkey-list">{keys.map(k=><div className="security-setting-row" key={k.id}><div><strong>{k.name}</strong><span>{k.last_used_at?'最近使用：'+date(k.last_used_at):'尚未使用'}</span></div><button type="button" className="secondary" disabled={busy} onClick={()=>{setSelected(k);setOperation('delete')}}>删除</button></div>)}{!keys.length&&<p className="security-description">尚未添加通行密钥。</p>}</div><div className="account-actions"><button type="button" disabled={busy||keys.length>=20} onClick={()=>setOperation('create')}><KeyRound size={16}/>添加通行密钥</button></div><Dialog open={!!operation} title={operation==='delete'?'删除通行密钥':'添加通行密钥'} onClose={()=>{if(!busy)setOperation(null)}}><p>{operation==='delete'?'删除后所有已登录会话会退出，请确认仍能使用密码或其他通行密钥登录。':'先确认当前账号，再根据浏览器提示创建通行密钥。'}</p><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void act(async()=>{const proof=stepup(f,'');if(operation==='create'){const init={method:'POST',headers:{'Content-Type':'application/json','X-API-Request':'1'},body:JSON.stringify({name:f.get('name'),current_password:proof.current_password,totp_code:proof.totp_code,__passkey:proof.__passkey})};const tools=await passkeyTools();const request=await tools.prepare('/account/v1/passkeys/register/begin',init);const response=await fetch(request);const start=await response.json();if(!response.ok)throw Error(start.error||'无法添加通行密钥');await tools.ceremony('register',{},start)}else{await api('/account/v1/passkeys/'+encodeURIComponent(selected!.id),'DELETE',proof);location.assign('/login');return}setOperation(null);await load();setMessage('通行密钥已添加')})}}>{operation==='create'&&<label>名称<input name="name" placeholder="例如：我的手机" maxLength={60} required autoComplete="off"/></label>}<Fields totp={profile.totp_enabled}/><div className="account-actions"><button type="button" className="secondary" disabled={busy} onClick={()=>setOperation(null)}>返回</button><button disabled={busy}>{operation==='create'?'确认并添加':'确认删除'}</button></div></form></Dialog></section>
}

function ConfirmationPreference({profile,busy,act,refresh,setMessage}:{profile:Profile;busy:boolean;act:(f:()=>Promise<void>)=>Promise<void>;refresh:()=>Promise<void>;setMessage:(s:string)=>void}){
 const [method,setMethod]=useState(profile.confirmation_method||'password'),[dialog,setDialog]=useState(false),[available,setAvailable]=useState(false);
 useEffect(()=>{setMethod(profile.confirmation_method||'password');void api<{passkey_available:boolean}>('/account/v1/confirmation-settings').then(v=>setAvailable(v.passkey_available)).catch(()=>{})},[profile.confirmation_method,profile.uid,dialog]);
 return <section className="account-panel confirmation-preference"><div className="security-card-heading"><div><h2>默认确认方式</h2><p>敏感操作统一使用这里设置的方式，前台与管理后台均生效。</p></div><span className="account-status neutral">{profile.confirmation_method==='passkey'?'通行密钥':'密码'}</span></div><div className="account-actions"><button type="button" disabled={busy} onClick={()=>setDialog(true)}>修改设置</button></div><Dialog open={dialog} title="默认确认方式" onClose={()=>{if(!busy)setDialog(false)}}><form onSubmit={e=>{e.preventDefault();const fields=new FormData(e.currentTarget);void act(async()=>{await api('/account/v1/confirmation-settings','PUT',{method,...stepup(fields,'')});(await passkeyTools()).resetPreference();broadcast();await refresh();setDialog(false);setMessage('默认确认方式已更新')})}}><label>敏感操作确认<select value={method} onChange={e=>setMethod(e.target.value as 'password'|'passkey')}><option value="password">密码确认</option><option value="passkey" disabled={!available}>通行密钥确认</option></select></label>{!available&&<p className="account-note">请先添加当前网站的通行密钥。</p>}<Fields totp={profile.totp_enabled}/><div className="account-actions"><button type="button" className="secondary" disabled={busy} onClick={()=>setDialog(false)}>返回</button><button disabled={busy}>确认并保存</button></div></form></Dialog></section>
}
